#include <iostream>
using namespace std;

// جنرک فنکشن جو کسی بھی ٹائپ کے دو نمبرز کو جمع کرے گا
template <typename T>
T add(T a, T b) {
    return a + b;
}

int main() {
    cout << add(5, 3) << endl;       // int
    cout << add(3.14, 2.71) << endl; // float
    cout << add<string>("Hello, ", "World!") << endl; // string
    return 0;
}
